import{_ as a,o as l,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"قانون ضمان الرعاية الصحية","description":"","frontmatter":{},"headers":[],"relativePath":"ar/44-医疗保障法.md","filePath":"ar/44-医疗保障法.md"}'),i={name:"ar/44-医疗保障法.md"};function e(o,t,h,n,s,b){return l(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="قانون-ضمان-الرعاية-الصحية" tabindex="-1">قانون ضمان الرعاية الصحية <a class="header-anchor" href="#قانون-ضمان-الرعاية-الصحية" aria-label="Permalink to &quot;قانون ضمان الرعاية الصحية&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>44</td></tr><tr><td>الوحدة</td><td>النظام القانوني وإطار الحوكمة</td></tr><tr><td>الكلمات المفتاحية</td><td>الحق في العلاج، الطب التكافلي، علاج إصابات الزراعة، الحياة والصحة، نظام التأمين الطبي</td></tr></tbody></table><h2 id="أولاً-الغرض-التشريعي-والمبادئ-الأساسية" tabindex="-1">أولاً: الغرض التشريعي والمبادئ الأساسية <a class="header-anchor" href="#أولاً-الغرض-التشريعي-والمبادئ-الأساسية" aria-label="Permalink to &quot;أولاً: الغرض التشريعي والمبادئ الأساسية&quot;">​</a></h2><p><em>قانون ضمان الرعاية الصحية</em> أحد القوانين الخمسة المساندة لحضارة التكافل المرساة. يهدف إلى ضمان حق الصحة والعلاج لجميع الكائنات داخل كون هنغ يوان، وإنشاء نظام طبي تكافلي يغطي عشرة آلاف عرق، وضمان حصول كل كائن على علاج فوري وفعال عند الإصابة أو المرض.</p><p>يحدد هذا القانون المبادئ الأساسية التالية:</p><table tabindex="0"><thead><tr><th>المبدأ</th><th>المضمون</th></tr></thead><tbody><tr><td>أولوية الصحة</td><td>الحياة والصحة أساس كل تطور؛ وتضع الدولة والحضارة حماية الحياة والصحة في موقع الأولوية</td></tr><tr><td>التغطية الشاملة</td><td>تغطي الضمانات الصحية جميع الكائنات، بغض النظر عن العرق أو الزراعة أو الأصل أو الوضع الاقتصادي</td></tr><tr><td>العلاج المدرج</td><td>إنشاء نظام علاجي ثلاثي المستويات — الطب الأساسي والطب الإقليمي والطب المتقدم — لتوزيع الموارد الطبية بعقلانية</td></tr><tr><td>الجمع بين الوقاية والعلاج</td><td>الوقاية أولاً والجمع بين الوقاية والعلاج؛ والاهتمام بالوقاية من إصابات الزراعة وإعادة تأهيلها</td></tr><tr><td>التكيف مع الأعراق الأخرى</td><td>تقديم خطط علاجية ملائمة للخصائص الفسيولوجية للأعراق المختلفة؛ وحظر تطبيق المعايير البشرية بشكل موحد</td></tr><tr><td>خاصية المصلحة العامة</td><td>الخدمات الطبية الأساسية ذات خاصية المصلحة العامة؛ ولا يجوز حرمان الكائنات من حق العلاج لأغراض الربح</td></tr></tbody></table><h2 id="ثانياً-الضمانات-القانونية-للحق-في-الحياة-والصحة" tabindex="-1">ثانياً: الضمانات القانونية للحق في الحياة والصحة <a class="header-anchor" href="#ثانياً-الضمانات-القانونية-للحق-في-الحياة-والصحة" aria-label="Permalink to &quot;ثانياً: الضمانات القانونية للحق في الحياة والصحة&quot;">​</a></h2><p>ينص هذا القانون صراحةً على أن الحق في الحياة والصحة حق أساسي يمنحه الدستور التكافلي لكل كائن، ويشمل على وجه التحديد:</p><ol><li><strong>الحق في العلاج الأساسي</strong>: لكل كائن الحق في الحصول على خدمات طبية أساسية مجانية، بما في ذلك تشخيص وعلاج الأمراض الشائعة والأدوية الأساسية والفحوصات الدورية وغيرها.</li><li><strong>الحق في الإسعاف</strong>: لكل كائن الحق في تلقي إسعاف عاجل عند الإصابة أو المرض المفاجئ؛ ولا يجوز للمؤسسات الطبية رفض الإسعاف لأي سبب.</li><li><strong>الحق في علاج إصابات الزراعة</strong>: للمزارعين الذين يعانون أثناء الزراعة من اضطرابات طاقية أو تلف خطوط الطاقة أو انحراف الزراعة وغيرها من الإصابات، الحق في تلقي علاج متخصص.</li><li><strong>الحق في الموافقة المستنيرة</strong>: للمريض الحق في معرفة حالته وخطة علاجه ومخاطره وتوقعاته، والحق في اختيار خطط العلاج أو رفضها.</li><li><strong>الحق في حماية الخصوصية</strong>: المعلومات الطبية والبيانات الجسدية للمريض محمية بالقانون؛ وبدون موافقة المريض لا يجوز إفشاؤها أو استخدامها لأغراض أخرى.</li><li><strong>الحق في ضمان إعادة التأهيل</strong>: للمصابين والمرضى الحق في تلقي علاج إعادة التأهيل والأجهزة المساعدة، لمساعدتهم على استعادة قدراتهم على العمل والمعيشة.</li></ol><h2 id="ثالثاً-بنية-النظام-الطبي-التكافلي" tabindex="-1">ثالثاً: بنية النظام الطبي التكافلي <a class="header-anchor" href="#ثالثاً-بنية-النظام-الطبي-التكافلي" aria-label="Permalink to &quot;ثالثاً: بنية النظام الطبي التكافلي&quot;">​</a></h2><p>ينقسم النظام الطبي في حضارة التكافل المرساة إلى ثلاثة مستويات، مع إنشاء آليات إحالة وتعاون بين المستويات:</p><table tabindex="0"><thead><tr><th>المستوى</th><th>الاسم</th><th>الوظائف</th><th>نطاق التغطية</th></tr></thead><tbody><tr><td>المستوى الأول</td><td>محطة الطب الأساسية</td><td>تشخيص وعلاج الأمراض الشائعة، الرعاية الوقائية، الفحوصات الأساسية، النقل العاجل</td><td>المجتمعات/القرى/الأبعاد الصغيرة</td></tr><tr><td>المستوى الثاني</td><td>المركز الطبي الإقليمي</td><td>التشخيص والعلاج التخصصي، العلاج الجراحي، المعالجة الأولية لإصابات الزراعة، إعادة التأهيل</td><td>المدن/المناطق/الأبعاد المتوسطة</td></tr><tr><td>المستوى الثالث</td><td>المستشفى الطبي المتقدم</td><td>الأمراض المستعصية والحرجة، إصابات الزراعة المتقدمة، أمراض مجال الوعي، الأمراض المستعصية العابرة للأعراق</td><td>قلب الحضارة/الأبعاد الكبيرة</td></tr></tbody></table><p>بالإضافة إلى ذلك، يُنشأ «تخصص إصابات الزراعة»: يتعامل خصيصاً مع جميع أنواع الإصابات أثناء الزراعة، بما في ذلك الحمل الزائد للطاقة، وتمزق خطوط الطاقة، وغزو شياطين القلب، وصدمات الروح وغيرها، ويجهز بكوادر طبية خبيرة بقوانين الزراعة.</p><h2 id="رابعاً-صندوق-الضمان-الطبي" tabindex="-1">رابعاً: صندوق الضمان الطبي <a class="header-anchor" href="#رابعاً-صندوق-الضمان-الطبي" aria-label="Permalink to &quot;رابعاً: صندوق الضمان الطبي&quot;">​</a></h2><p>صندوق الضمان الطبي هو الأساس الاقتصادي لتشغيل النظام الطبي التكافلي، وتشمل موارده:</p><ul><li>مخصصات التراكم العام (المصدر الرئيسي)</li><li>اقتطاعات الضمان الطبي في آلية التعاقد المشترك على الإنتاج</li><li>التبرعات الاجتماعية</li><li>عوائد استثمارات الصندوق</li></ul><p>يشمل نطاق دفع الصندوق: تكاليف الخدمات الطبية الأساسية، وتكاليف الإسعاف، وتكاليف علاج إصابات الزراعة، وتكاليف الأدوية الأساسية، وتكاليف إعادة التأهيل وغيرها. لا يدفع المريض سوى مبلغ صغير من التكاليف الشخصية، مع تخفيضات وإعفاءات لمن يعانون صعوبات اقتصادية.</p><h2 id="خامساً-المؤسسات-الطبية-والكوادر-الطبية" tabindex="-1">خامساً: المؤسسات الطبية والكوادر الطبية <a class="header-anchor" href="#خامساً-المؤسسات-الطبية-والكوادر-الطبية" aria-label="Permalink to &quot;خامساً: المؤسسات الطبية والكوادر الطبية&quot;">​</a></h2><ul><li><strong>المؤسسات الطبية العامة</strong>: تنشئها الدولة أو جماعة الحضارة، وتتولى الخدمات الطبية الأساسية ووظائف الصحة العامة، بتمويل مضمون من صندوق الضمان الطبي.</li><li><strong>المؤسسات الطبية الخاصة</strong>: تنشئها القوى الاجتماعية وفقاً للقانون؛ ويمكنها تقديم خدمات طبية راقية، لكن يجب أن تخضع لإشراف السلطات الطبية المختصة، ولا يجوز لها رفض مرضى الإسعاف.</li><li><strong>المؤسسات الطبية للأعراق الأخرى</strong>: مؤسسات طبية تخصصية تنشأ لتلبية الاحتياجات الفسيولوجية للأعراق الخاصة، وتجهز بكادر طبي من الأعراق الأخرى.</li><li><strong>حقوق وواجبات الكوادر الطبية</strong>: يتمتع الكادر الطبي بحقوق الحماية المهنية والأجر المعقول والتدريب المهني، ويحمل في الوقت نفسه واجبات إنقاذ الأرواح واحترام المرضى وكتمان السر الطبي.</li></ul><h2 id="سادساً-الصحة-العامة-والوقاية" tabindex="-1">سادساً: الصحة العامة والوقاية <a class="header-anchor" href="#سادساً-الصحة-العامة-والوقاية" aria-label="Permalink to &quot;سادساً: الصحة العامة والوقاية&quot;">​</a></h2><p>تنشئ الدولة نظام الصحة العامة، وتؤدي الوظائف التالية:</p><ol><li>مراقبة الأمراض المعدية والوقاية منها، وإنشاء آلية إنذار مبكر للأوبئة عبر الأبعاد.</li><li>الفحوصات الصحية الشاملة وإدارة السجلات الصحية.</li><li>التوعية بسلامة الزراعة وتوجيه الوقاية من إصابات الزراعة.</li><li>الإشراف على النظافة البيئية وسلامة الأغذية والأدوية.</li><li>الاستجابة الطارئة لأحداث الصحة العامة.</li></ol><h2 id="سابعاً-المسؤولية-القانونية" tabindex="-1">سابعاً: المسؤولية القانونية <a class="header-anchor" href="#سابعاً-المسؤولية-القانونية" aria-label="Permalink to &quot;سابعاً: المسؤولية القانونية&quot;">​</a></h2><p>تتحمل الأفعال المخالفة لأحكام هذا القانون المسؤوليات التالية حسب جسامة الظروف:</p><ul><li>المؤسسات الطبية التي ترفض مرضى الإسعاف: الأمر بالتصحيح ودفع غرامة، وفي حال حدوث عواقب وخيمة إلغاء ترخيص المزاولة.</li><li>الكوادر الطبية التي تسبب ضرراً للمرضى بإهمال جسيم: تحمل مسؤولية التعويض، وفي الحالات الجسيمة إلغاء صفة المزاولة.</li><li>المؤسسات الطبية التي تتقاضى رسوماً مخالفة أو تقدم علاجاً مفرطاً: الأمر بإرجاع الرسوم ودفع غرامة.</li><li>من يفشي الخصوصية الطبية للمرضى: تحمل تعويض الضرر المعنوي، وفي الحالات الجسيمة تطبيق المسؤولية الجنائية.</li><li>من ينتج ويبيع أدوية مزيفة أو رديئة: مصادرة العائدات غير المشروعة ودفع غرامة، وفي حال تشكيل جريمة تطبيق المسؤولية الجنائية.</li></ul><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p><em>قانون ضمان الرعاية الصحية</em> هو تجسيد فلسفة «لكل فرد طريق» في حضارة التكافل المرساة في مجال الصحة. بإنشاء نظام ضمان طبي شامل التغطية، وتخصيص تخصص لإصابات الزراعة، وضمان الحق في الإسعاف، يضمن حصول كل كائن على علاج فوري عند الإصابة أو المرض، ويضع أساساً صحياً متيناً لتقدم عشرة آلاف عرق معاً.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>40-共生宪法总纲 (الدستور التكافلي: المبادئ العامة)</li><li>38-共生医疗体系 (نظام الرعاية الطبية التكافلي)</li><li>45-住房保障法 (قانون ضمان الإسكان)</li><li>08-人人有路保障体系 (نظام ضمان طريق لكل فرد)</li></ul>',29)])])}const p=a(i,[["render",e]]);export{u as __pageData,p as default};
